CREATE FUNCTION public.is_trip_customer(trip uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.bookings WHERE tour_id=trip AND tourist_id=auth.uid()) $$; REVOKE ALL ON FUNCTION public.is_trip_customer(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_trip_customer(uuid) TO authenticated; DROP POLICY booked_tour_read ON public.tours; CREATE POLICY booked_tour_read ON public.tours FOR SELECT TO authenticated USING(public.is_trip_customer(id));